func (d decisionDo) Preload(fields ...field.RelationField) IDecisionDo {
	for _, _f := range fields {
		d = *d.withDO(d.DO.Preload(_f))
	}
	return &d
}

func (d decisionDo) FirstOrInit() (*model.Decision, error) {
	if result, err := d.DO.FirstOrInit(); err != nil {
		return nil, err
	} else {
		return result.(*model.Decision), nil
	}
}

func (d decisionDo) FirstOrCreate() (*model.Decision, error) {
	if result, err := d.DO.FirstOrCreate(); err != nil {
		return nil, err
	} else {
		return result.(*model.Decision), nil
	}
}

func (d decisionDo) FindByPage(offset int, limit int) (result []*model.Decision, count int64, err error) {
	result, err = d.Offset(offset).Limit(limit).Find()
	if err != nil {
		return
	}

	if size := len(result); 0 < limit && 0 < size && size < limit {
		count = int64(size + offset)
		return
	}

	count, err = d.Offset(-1).Limit(-1).Count()
	return
}

func (d decisionDo) ScanByPage(result interface{}, offset int, limit int) (count int64, err error) {
	count, err = d.Count()
	if err != nil {
		return
	}

	err = d.Offset(offset).Limit(limit).Scan(result)
	return
}

func (d decisionDo) Scan(result interface{}) (err error) {
	return d.DO.Scan(result)
}

func (d decisionDo) Delete(models ...*model.Decision) (result gen.ResultInfo, err error) {
	return d.DO.Delete(models)
}

func (d *decisionDo) withDO(do gen.Dao) *decisionDo {
	d.DO = *do.(*gen.DO)
	return d
}
